<h1>Admission cycles</h1><?php if (session('message')): ?><p><?= esc(session('message')) ?></p><?php endif ?><?php if (session('errors')): ?><ul><?php foreach(session('errors') as $error): ?><li><?= esc($error) ?></li><?php endforeach ?></ul><?php endif ?>
<form method="post" action="<?= site_url('tenant/admissions/cycles') ?>"><?= csrf_field() ?><h2>Create or update cycle</h2><label>Cycle ID for update <input name="id" inputmode="numeric"></label><label>Academic session <select name="academic_session_id" required><?php foreach($academicSessions as $session): ?><option value="<?= esc($session['id']) ?>"><?= esc($session['name']) ?></option><?php endforeach ?></select></label><label>Title <input name="title" required></label><label>Code <input name="code" required></label><label>Opens at <input type="datetime-local" name="opens_at" required></label><label>Closes at <input type="datetime-local" name="closes_at" required></label><label>Status <select name="status"><option>draft</option><option>scheduled</option><option>open</option></select></label><input type="hidden" name="is_public" value="0"><label><input type="checkbox" name="is_public" value="1"> Publicly visible</label><input type="hidden" name="allow_multiple_public_cycles" value="0"><label><input type="checkbox" name="allow_multiple_public_cycles" value="1"> Allow multiple public cycles</label><label>Instructions <textarea name="instructions"></textarea></label><label>Screening instructions <textarea name="screening_instructions"></textarea></label><button>Save cycle</button></form>
<h2>Configured cycles</h2><div class="admin-grid"><?php foreach($cycles as $cycle): ?><article class="admin-card"><strong><?= esc($cycle['title']) ?></strong><br><?= esc($cycle['code']) ?> — <?= esc($cycle['status']) ?><form class="inline-form" method="post" action="<?= site_url('tenant/admissions/cycles/'.$cycle['id'].'/transition/open') ?>"><?= csrf_field() ?><button>Open</button></form><form class="inline-form" method="post" action="<?= site_url('tenant/admissions/cycles/'.$cycle['id'].'/transition/closed') ?>"><?= csrf_field() ?><button>Close</button></form><form class="inline-form" method="post" action="<?= site_url('tenant/admissions/cycles/'.$cycle['id'].'/transition/under_review') ?>"><?= csrf_field() ?><button>Start review</button></form><form class="inline-form" method="post" action="<?= site_url('tenant/admissions/cycles/'.$cycle['id'].'/transition/archived') ?>"><?= csrf_field() ?><button>Archive</button></form></article><?php endforeach ?></div>
